
(()=>{
  const GYM_SIGN_PRIMARY="data:image/png;base64,";
  const GYM_SIGN_FALLBACK="data:image/png;base64,";
  const makeGymIcon=(kind="inline",alt="Gimnasio")=>{
    const img=document.createElement("img");
    img.className=`gym-official-icon ${kind}`;img.alt=alt;img.src=GYM_SIGN_PRIMARY;
    img.addEventListener("error",()=>{if(img.dataset.fallbackTried)return;img.dataset.fallbackTried="1";img.src=GYM_SIGN_FALLBACK;},{once:true});
    return img;
  };
  const prependGymIcon=(el,kind="inline",text=null)=>{
    if(!el||el.dataset.gymOfficialSprite==="1")return;
    if(text!==null)el.textContent=text;
    el.prepend(makeGymIcon(kind));el.dataset.gymOfficialSprite="1";
  };
  function applyGymOfficialSprites(){
    const hud=document.getElementById("gymHudBtn");
    if(hud&&hud.dataset.gymOfficialSprite!=="1"){
      hud.replaceChildren(makeGymIcon("nav"));hud.dataset.gymOfficialSprite="1";
    }
    const selectTitle=document.getElementById("gymSelectTitle");
    if(selectTitle){prependGymIcon(selectTitle,"title","Gimnasios de Kanto");selectTitle.classList.add("gym-official-title");}
    const ach=document.querySelector('[data-achievement-filter="gyms"]');
    if(ach)prependGymIcon(ach,"tab","Gimnasios");
    const helpTab=document.querySelector('[data-help-tab="gyms"]');
    if(helpTab)prependGymIcon(helpTab,"tab","Gimnasios");
    document.querySelectorAll("#infoPanel .help-mini-card b,#infoPanel .help-hero h3").forEach(el=>{
      const raw=(el.textContent||"").trim().replace(/^🏛️?\s*/,"");
      if(["Líderes de Gimnasio","Gimnasios","Gimnasios de Kanto"].includes(raw))prependGymIcon(el,"inline",raw);
    });
    const battleKicker=document.getElementById("gymBattleKicker");
    if(battleKicker){prependGymIcon(battleKicker,"tab","Gimnasio");battleKicker.classList.add("gym-kicker-with-icon");}
    const resultKicker=document.getElementById("gymResultKicker");
    if(resultKicker&&resultKicker.dataset.gymOfficialSprite!=="1"){
      const t=(resultKicker.textContent||"Gimnasio de Kanto").replace(/^🏛️?\s*/,"");prependGymIcon(resultKicker,"tab",t);resultKicker.classList.add("gym-kicker-with-icon");
    }
    const back=document.getElementById("gymResultContinueBtn");
    if(back) { prependGymIcon(back,"tab","Volver a Gimnasios"); back.classList.add("gym-return-with-icon"); }
  }
  applyGymOfficialSprites();setTimeout(applyGymOfficialSprites,500);setTimeout(applyGymOfficialSprites,1500);
})();
